namespace Shop.SqlTests;
public sealed class ChequeReportSqlTests():CreditRequirementsSqlBase(new SqlFixture()),IAsyncLifetime
{
    private WebApplicationFactory<Program>? auth;private Task<HttpClient> Staff(string role)=>base.Staff(role,auth??=sql.Factory.WithWebHostBuilder(_=>{}));public Task InitializeAsync()=>sql.InitializeAsync();public async Task DisposeAsync(){auth?.Dispose();await sql.DisposeAsync();}
    private sealed record Scenario(HttpClient Customer,string Owner,string Order,JsonNode[] Cheques);
    private static string V(JsonNode n,string k)=>CreditCheckoutQuoteQa.Text(n,k);
    private static string Today=>ChequeReportRules.Today(DateTimeOffset.UtcNow);
    private static string Route(string state="All",string? cursor=null)=>"/api/admin/credit/cheque-report?from="+Today+"&through="+ChequeReportRules.Date(Today).AddDays(365).ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture)+"&state="+state+(cursor is null?"":"&cursor="+Uri.EscapeDataString(cursor));
    private static async Task<JsonNode> Report(HttpResponseMessage response)
    {
        using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"HTTP{(int)response.StatusCode}: {raw}");Assert.Contains("no-store",response.Headers.CacheControl!.ToString());Assert.Contains("noindex",response.Headers.GetValues("X-Robots-Tag").Single());Assert.False(response.Headers.Contains("Set-Cookie"));if(Environment.GetEnvironmentVariable("SHOP_CHEQUE_REPORT_WIRE_DIR")is{Length:>0}dir){Directory.CreateDirectory(dir);var id=Id();await File.WriteAllTextAsync(Path.Combine(dir,id+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,id+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,method="GET",path=response.RequestMessage!.RequestUri!.PathAndQuery}));}return JsonNode.Parse(raw)!;}
    }
    private async Task<Scenario> Ready(HttpClient f,HttpClient reviewer)
    {
        using var helper=new CreditOrderSqlTests(sql);var s=await helper.Ready(f,reviewer);var result=await CreditOrderQa.Read(await s.Customer.PostAsJsonAsync("/api/credit-orders/commands/"+Id(),new CreditOrderInput(V(s.Quote,"id"),V(s.Quote,"fingerprint"),"Synthetic report QA","09100000000",new("IR","تهران","تهران","Synthetic report only, no actual person or funds","1234567890"),"QA only",true,true)));var summary=result["order"]!["summary"]!;var id=V(summary,"id");var path="/api/admin/credit/orders/"+s.Owner+"/"+id;var pi=new CreditSchedulePreviewInput(V(summary,"version"),null,"Gregorian",Today);var preview=await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/schedule/preview",pi));var schedule=(await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/schedule/commands/"+Id(),new SaveCreditScheduleInput(pi.OrderVersion,null,"Gregorian",Today,V(preview,"fingerprint"),true))))["revision"]!;var cheques=new List<JsonNode>();foreach(var line in schedule["calculation"]!["lines"]!.AsArray()){var r=await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/cheques/receive/commands/"+Id(),new ReceiveChequeInput(pi.OrderVersion,V(schedule,"version"),line!["sequence"]!.GetValue<int>(),"SYNTHETIC-PRIVATE-INSTRUMENT","SYNTHETIC-PRIVATE-RECEIPT-NOTE",DateTimeOffset.UtcNow,true)));cheques.Add(r["cheque"]!.DeepClone());}await CreditOrderQa.Read(await s.Customer.PostAsJsonAsync("/api/orders/v2/"+id+"/cancel",new{version=pi.OrderVersion}));return new(s.Customer,s.Owner,id,cheques.ToArray());
    }
    private async Task<string> FinancialDigest()
    {
        await using var scope=sql.Factory.Services.CreateAsyncScope();var c=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var s=scope.ServiceProvider.GetRequiredService<SalesDbContext>();var i=scope.ServiceProvider.GetRequiredService<IdentityContext>();var data=new{Cheques=await c.ReceivedCheques.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync(),Events=await c.ChequeLedgerEvents.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync(),Commands=await c.ChequeLedgerCommands.AsNoTracking().OrderBy(x=>x.CommandId).ToArrayAsync(),Orders=await s.Orders.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync(),Uses=await c.PurchaseScopeUses.AsNoTracking().OrderBy(x=>x.OrderId).ToArrayAsync(),Audit=await i.Audit.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync()};return Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(data)));
    }
    [Fact]public async Task TwentyFourVerifiedChequesPageWithoutDuplicatesAndReportDoesNotWriteFinancialData()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var scenarios=new List<Scenario>();try{for(var i=0;i<4;i++)scenarios.Add(await Ready(f,reviewer));var before=await FinancialDigest();var first=await Report(await f.GetAsync(Route()));Assert.Equal(20,first["items"]!.AsArray().Count);var cursor=V(first,"nextCursor");var second=await Report(await f.GetAsync(Route(cursor:cursor)));Assert.Equal(4,second["items"]!.AsArray().Count);Assert.Null(second["nextCursor"]);Assert.Equal(V(first,"registrationCutoff"),V(second,"registrationCutoff"));var rows=first["items"]!.AsArray().Concat(second["items"]!.AsArray()).Select(x=>x!).ToArray();Assert.Equal(24,rows.Select(x=>V(x["cheque"]!,"id")).Distinct().Count());Assert.All(rows,x=>Assert.Equal("Cancelled",V(x["currentOrder"]!,"state")));Assert.All(new[]{first,second},p=>{Assert.False(p["bankVerified"]!.GetValue<bool>());Assert.False(p["canPay"]!.GetValue<bool>());Assert.False(p["canFulfill"]!.GetValue<bool>());Assert.DoesNotContain("SYNTHETIC-PRIVATE",p.ToJsonString());Assert.DoesNotContain("instrumentReference",p.ToJsonString());Assert.DoesNotContain("contactPhone",p.ToJsonString());var sum=p["items"]!.AsArray().Aggregate(System.Numerics.BigInteger.Zero,(v,x)=>v+System.Numerics.BigInteger.Parse(V(x!["cheque"]!,"amountRial")));Assert.Equal(sum.ToString(),V(p["pageTotals"]!,"amountRial"));});Assert.Equal(before,await FinancialDigest());var later=await Ready(f,reviewer);scenarios.Add(later);var continuation=await Report(await f.GetAsync(Route(cursor:cursor)));Assert.Equal(4,continuation["items"]!.AsArray().Count);Assert.DoesNotContain(continuation["items"]!.AsArray(),x=>V(x!["currentOrder"]!,"orderId")==later.Order);var fresh=await Report(await f.GetAsync(Route()));Assert.Equal(20,fresh["items"]!.AsArray().Count);var freshLast=await Report(await f.GetAsync(Route(cursor:V(fresh,"nextCursor"))));Assert.Equal(10,freshLast["items"]!.AsArray().Count);}finally{foreach(var s in scenarios)s.Customer.Dispose();}
    }
    private sealed class FutureClock(DateTimeOffset time):TimeProvider{public override DateTimeOffset GetUtcNow()=>time;}
    [Fact]public async Task CursorCannotCrossActorFilterOrExpiryAndQueryMustBeExact()
    {
        using var f=await Staff("FinanceManager");using var other=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var scenarios=new List<Scenario>();try{for(var i=0;i<4;i++)scenarios.Add(await Ready(f,reviewer));var first=await Report(await f.GetAsync(Route()));var cursor=V(first,"nextCursor");foreach(var path in new[]{Route("Received",cursor),Route(cursor:cursor+"="),Route()+"&unknown=x",Route()+"&state=All",Route().Replace(Today,"2026-02-30"),"/api/admin/credit/cheque-report?from=2026-01-01&through=2027-01-02&state=All"}){using var bad=await f.GetAsync(path);Assert.Equal(HttpStatusCode.BadRequest,bad.StatusCode);}using(var denied=await other.GetAsync(Route(cursor:cursor)))Assert.Equal(HttpStatusCode.BadRequest,denied.StatusCode);await using var later=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(s=>s.AddSingleton<TimeProvider>(new FutureClock(DateTimeOffset.Parse(V(first,"cursorExpiresAt"))))));using var client=later.CreateClient(new(){HandleCookies=false});foreach(var h in f.DefaultRequestHeaders)client.DefaultRequestHeaders.TryAddWithoutValidation(h.Key,h.Value);using var expired=await client.GetAsync(Route(cursor:cursor));Assert.Equal(HttpStatusCode.Conflict,expired.StatusCode);}finally{foreach(var s in scenarios)s.Customer.Dispose();}
    }
    [Fact]public async Task RolePrivacyCurrentLedgerFilterCorruptSealAndIndexDownAreEnforced()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var sales=await Staff("SalesManager");var s=await Ready(f,reviewer);using var customer=s.Customer;using(var anonymous=sql.Factory.CreateClient(new(){HandleCookies=false})){using var denied=await anonymous.GetAsync(Route());Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);}foreach(var deniedClient in new[]{reviewer,sales,customer}){using var denied=await deniedClient.GetAsync(Route());Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);}var cheque=s.Cheques[0];var path="/api/admin/credit/orders/"+s.Owner+"/"+s.Order+"/cheques/"+V(cheque,"id")+"/commands/"+Id();await CreditScheduleQa.Read(await f.PostAsJsonAsync(path,new MoveChequeInput(V(cheque,"version"),"Deposit","Synthetic after cancellation custody",DateTimeOffset.UtcNow,true,true)));var deposited=await Report(await f.GetAsync(Route("Deposited")));Assert.Single(deposited["items"]!.AsArray());Assert.Equal(V(cheque,"id"),V(deposited["items"]![0]!["cheque"]!,"id"));var received=await Report(await f.GetAsync(Route("Received")));Assert.Equal(5,received["items"]!.AsArray().Count);await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();Assert.False(db.Database.HasPendingModelChanges());await db.GetService<IMigrator>().MigrateAsync("20261027231139_CreditFinancialClearance");Assert.Equal(6,await db.ReceivedCheques.CountAsync());await db.GetService<IMigrator>().MigrateAsync();await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ReceivedCheques] SET [ProtectedRegistration]={new byte[]{1,2,3}} WHERE [Id]={V(cheque,"id")}");}using var corrupt=await f.GetAsync(Route());Assert.Equal(HttpStatusCode.ServiceUnavailable,corrupt.StatusCode);
    }
    private sealed class BeforeOwner(ICreditOrderScheduleSource inner,Func<Task> change):ICreditOrderScheduleSource
    {
        public bool Triggered;
        public Task<CreditScheduleOrderPageSource> PageForFinanceAsync(string? cursor,CancellationToken ct)=>inner.PageForFinanceAsync(cursor,ct);
        public async Task<CreditOrderScheduleSource> LockAndReadAsync(string owner,string order,CancellationToken ct){if(!Triggered){Triggered=true;await change();}return await inner.LockAndReadAsync(owner,order,ct);}
    }
    [Fact]public async Task LedgerRaceBetweenCandidateAndOwnerGateReturnsConflictRatherThanPartialPage()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var cheque=s.Cheques[0];BeforeOwner? hook=null;Func<Task> change=async()=>{await CreditScheduleQa.Read(await f.PostAsJsonAsync("/api/admin/credit/orders/"+s.Owner+"/"+s.Order+"/cheques/"+V(cheque,"id")+"/commands/"+Id(),new MoveChequeInput(V(cheque,"version"),"Deposit","Synthetic precise report read race",DateTimeOffset.UtcNow,true,true)));};await using var factory=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(services=>services.AddScoped<ICreditOrderScheduleSource>(sp=>hook=new BeforeOwner(ActivatorUtilities.CreateInstance<SalesCreditOrderScheduleSource>(sp),change))));using var client=factory.CreateClient(new(){HandleCookies=false});foreach(var h in f.DefaultRequestHeaders)client.DefaultRequestHeaders.TryAddWithoutValidation(h.Key,h.Value);using var conflict=await client.GetAsync(Route());Assert.True(hook?.Triggered);Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);var problem=JsonNode.Parse(await conflict.Content.ReadAsStringAsync())!;Assert.Equal("cheque_report_changed_conflict",V(problem,"title"));var fresh=await Report(await f.GetAsync(Route()));Assert.Equal(6,fresh["items"]!.AsArray().Count);
    }
}
